{
  "name": "@igorvelho/opencode-kiro-auth",
  "version": "1.8.4",
  "description": "OpenCode plugin for AWS Kiro (CodeWhisperer) - forked with updated model support (minimax-m2.5, glm-5, deepseek-3.2, qwen3-coder-next)",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "format": "prettier --write 'src/**/*.ts'",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "prepare": "husky"
  },
  "keywords": [
    "opencode",
    "plugin",
    "kiro",
    "codewhisperer",
    "aws",
    "claude",
    "ai",
    "auth"
  ],
  "author": "igorvelho",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/igorvelho/opencode-kiro-auth.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.2.6",
    "proper-lockfile": "^4.1.2",
    "zod": "^3.24.0"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
    "@types/proper-lockfile": "^4.1.4",
    "bun-types": "^1.3.6",
    "husky": "^9.1.7",
    "lint-staged": "^16.2.7",
    "prettier": "^3.4.2",
    "prettier-plugin-organize-imports": "^4.1.0",
    "typescript": "^5.7.3"
  },
  "opencode": {
    "type": "plugin",
    "hooks": [
      "auth",
      "event"
    ]
  },
  "files": [
    "dist",
    "package.json",
    "README.md"
  ],
  "lint-staged": {
    "*.ts": [
      "prettier --write"
    ]
  }
}
